modern_c2_q7.program:
def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    suitcase_patches = image_patch.find("suitcase")
    luggage_patches = image_patch.find("luggage")

    if not suitcase_patches or not luggage_patches:
        return image_patch

    suitcase = suitcase_patches[0]
    red_luggage = [l for l in luggage_patches if l.verify_property("luggage", "red")]

    if not red_luggage:
        return suitcase

    min_distance = float('inf')
    closest_luggage = None

    for luggage in red_luggage:
        dist = abs(suitcase.left - luggage.right)
        if dist < min_distance:
            min_distance = dist
            closest_luggage = luggage

    if closest_luggage and closest_luggage.right < suitcase.left:
        return suitcase

    return closest_luggage

