def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    bear_patches = image_patch.find("bear")
    if not bear_patches:
        return image_patch
    bear_patches.sort(key=lambda p: p.compute_depth())
    front_bear = bear_patches[0]
    for bear in bear_patches[1:]:
        if bear.compute_depth() > front_bear.compute_depth():
            front_bear = bear
    return front_bear

